export class Skills {
  constructor(hardSkills, softSkills) {
    this._hardSkills = hardSkills;
    this._softSkills = softSkills;
  }
  get hardSkills() {
    return this._hardSkills;
  }
  set hardSkills(hardSkills) {
    this._hardSkills = hardSkills;
  }
  get softSkills() {
    return this._softSkills;
  }
  set softSkills(softSkills) {
    this._softSkills = softSkills;
  }
}
